'use client';

import {
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { useReducedMotion } from './use-reduced-motion';
import './reading-progress-rail.css';

export interface ReadingSection {
  id: string;
  title: string;
  body: ReactNode;
}

export interface ReadingProgressRailProps {
  sections: ReadingSection[];
  /** Accessible name for the article. */
  label: string;
  className?: string;
}

/**
 * A scrollable article with a rail that fills as you read and marks the
 * section you are in. Section buttons jump within the article only; the
 * page around it never scrolls.
 */
export function ReadingProgressRail({
  sections,
  label,
  className = '',
}: ReadingProgressRailProps) {
  const article = useRef<HTMLDivElement>(null);
  const [progress, setProgress] = useState(0);
  const [current, setCurrent] = useState(0);
  const reduced = useReducedMotion();

  useEffect(() => {
    const el = article.current;
    if (!el) return;
    let frame = 0;
    const update = () => {
      frame = 0;
      const max = el.scrollHeight - el.clientHeight;
      setProgress(max > 0 ? el.scrollTop / max : 1);
      const line = el.scrollTop + el.clientHeight * 0.3;
      const heads = Array.from(
        el.querySelectorAll<HTMLElement>('[data-section]')
      );
      let index = 0;
      heads.forEach((head, i) => {
        if (head.offsetTop <= line) index = i;
      });
      if (max > 0 && el.scrollTop >= max - 2) index = heads.length - 1;
      setCurrent(index);
    };
    const onScroll = () => {
      if (!frame) frame = requestAnimationFrame(update);
    };
    update();
    el.addEventListener('scroll', onScroll, { passive: true });
    return () => {
      el.removeEventListener('scroll', onScroll);
      cancelAnimationFrame(frame);
    };
  }, [sections]);

  const jump = (index: number) => {
    const el = article.current;
    const head = el?.querySelector<HTMLElement>(`[data-section="${index}"]`);
    if (el && head)
      el.scrollTo({
        top: head.offsetTop - 8,
        behavior: reduced ? 'auto' : 'smooth',
      });
  };

  return (
    <div
      className={`mg-read ${className}`}
      style={{ '--mg-progress': progress } as CSSProperties}
    >
      <nav className='mg-read__rail' aria-label={`${label} sections`}>
        <span className='mg-read__track' aria-hidden='true'>
          <span className='mg-read__fill' />
        </span>
        <ol>
          {sections.map((section, index) => (
            <li key={section.id}>
              <button
                type='button'
                aria-current={index === current ? 'location' : undefined}
                onClick={() => jump(index)}
              >
                {section.title}
              </button>
            </li>
          ))}
        </ol>
        <span className='mg-read__pct'>{Math.round(progress * 100)}% read</span>
      </nav>
      <div
        ref={article}
        className='mg-read__article'
        tabIndex={0}
        role='region'
        aria-label={label}
      >
        {sections.map((section, index) => (
          <section key={section.id} data-section={index}>
            <h4>{section.title}</h4>
            {section.body}
          </section>
        ))}
      </div>
    </div>
  );
}

.mg-read {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr);
  gap: 12px;
  height: 240px;
  color: var(--mg-text, #ffffff);
}

.mg-read__rail {
  position: relative;
  display: flex;
  flex-direction: column;
  padding-left: 14px;
  font-size: 13px;
}

.mg-read__track {
  position: absolute;
  top: 4px;
  bottom: 28px;
  left: 0;
  width: 4px;
  overflow: hidden;
  border-radius: 2px;
  background: var(--mg-line, #303030);
}

.mg-read__fill {
  display: block;
  height: 100%;
  background: var(--mg-accent, #0047ff);
  transform: scaleY(var(--mg-progress));
  transform-origin: top;
  transition: transform 120ms linear;
}

.mg-read__rail ol {
  display: grid;
  gap: 2px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.mg-read__rail button {
  width: 100%;
  min-height: 36px;
  padding: 0 6px;
  border: 0;
  border-radius: 6px;
  background: none;
  color: #b8b8b8;
  font: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 200ms ease,
    color 200ms ease;
}

.mg-read__rail button[aria-current] {
  background: #141d38;
  color: var(--mg-text, #ffffff);
  font-weight: 700;
}

.mg-read__rail button[aria-current]::before {
  content: '▸ ';
  color: var(--mg-accent-text, #648aff);
}

.mg-read__rail button:focus-visible,
.mg-read__article:focus-visible {
  outline: 2px solid var(--mg-accent-text, #648aff);
  outline-offset: 1px;
}

.mg-read__pct {
  margin-top: auto;
  color: #b8b8b8;
  font-variant-numeric: tabular-nums;
}

.mg-read__article {
  /* Children measure their offsets from here. */
  position: relative;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 4px 14px 80px;
  border: 1px solid var(--mg-line, #303030);
  border-radius: 12px;
  background: #121212;
  color: #b8b8b8;
}

.mg-read__article h4 {
  margin: 14px 0 6px;
  color: var(--mg-text, #ffffff);
  font-size: 15px;
}

.mg-read__article p {
  margin: 0 0 8px;
}

@media (prefers-reduced-motion: reduce) {
  .mg-read__fill,
  .mg-read__rail button {
    transition: none;
  }
}

'use client';

import { useEffect, useState } from 'react';

/** True when the user has asked for reduced motion. Follows live changes. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}
